#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
using Yarn.Unity;

// Explicit player-only verification; all campaign mutations and archives are isolated.
public sealed class JournalHistoryCapture:MonoBehaviour
{
    string folder;readonly List<string> checks=new List<string>();VariableSingleton.CampaignSave baseline;EventUI events;DialogueRunner runner;ManagerUI manager;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){if(!Environment.GetCommandLineArgs().Contains("-journal-history-capture"))return;string path=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/JournalHistory"));Directory.CreateDirectory(path);SaveGames.TestRoot=Path.Combine(path,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.json");var go=new GameObject("Journal history verification");DontDestroyOnLoad(go);go.AddComponent<JournalHistoryCapture>().folder=path;}
    void Check(bool value,string message){if(!value)throw new Exception(message);checks.Add("PASS "+message);}
    string State()=>JsonUtility.ToJson(VariableSingleton.Instance.CaptureState());
    void Reset(){if(runner!=null&&runner.IsDialogueRunning)runner.Stop();events.gameObject.SetActive(false);CampaignHUD.Instance.DismissReport();DecisionJournal.Close();VariableSingleton.Instance.RestoreValidated(JsonUtility.FromJson<VariableSingleton.CampaignSave>(JsonUtility.ToJson(baseline)));DecisionJournal.Entries.Clear();PalaceAdministration.Baseline();}
    IEnumerator Start(){Application.runInBackground=true;AudioListener.volume=0;File.WriteAllText(Path.Combine(folder,"checks.txt"),"RUNNING");var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){object next=null;bool more=false;Exception failure=null;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception e){failure=e;}if(failure!=null){File.WriteAllLines(Path.Combine(folder,"details.txt"),checks);File.WriteAllText(Path.Combine(folder,"checks.txt"),"FAILED "+checks.Count+"\n"+failure);Debug.LogException(failure);Application.Quit(1);yield break;}if(!more){stack.Pop();continue;}if(next is IEnumerator nested)stack.Push(nested);else yield return next;}File.WriteAllLines(Path.Combine(folder,"details.txt"),checks);File.WriteAllText(Path.Combine(folder,"checks.txt"),checks.Count+" journal history checks passed");Application.Quit(0);}
    IEnumerator OpenEvent(string node){if(runner.IsDialogueRunning)runner.Stop();events.gameObject.SetActive(false);CampaignHUD.Instance.DismissReport();manager.gameObject.SetActive(false);events.SetStartNode(node);events.gameObject.SetActive(true);float end=Time.realtimeSinceStartup+12;while(!FindObjectsOfType<OptionButton>().Any(o=>o.IsInteractable())&&Time.realtimeSinceStartup<end)yield return null;Check(FindObjectsOfType<OptionButton>().Any(o=>o.IsInteractable()),"actual event choices ready "+node);}
    IEnumerator FinishDialogue(){float end=Time.realtimeSinceStartup+12;while(runner.IsDialogueRunning&&Time.realtimeSinceStartup<end)yield return null;Check(!runner.IsDialogueRunning&&CampaignHUD.Instance.HasModal,"actual event completes to outcome");}
    GameObject Reader()=>GameObject.Find("Recorded event reader");
    Button ReaderButton(string name)=>Reader().GetComponentsInChildren<Button>().First(b=>b.name==name);
    IEnumerator Run(){yield return null;SaveMenu.StartCampaign(false);float end=Time.realtimeSinceStartup+20;while(!VariableSingleton.IsInitialized&&Time.realtimeSinceStartup<end)yield return null;yield return new WaitForSecondsRealtime(.5f);Check(VariableSingleton.IsInitialized,"campaign initialized");CampaignHUD.Instance.DismissReport();manager=FindObjectOfType<ManagerUI>(true);events=FindObjectOfType<EventUI>(true);runner=events.GetComponentInChildren<DialogueRunner>(true);baseline=VariableSingleton.Instance.CaptureState();
        Reset();VariableSingleton.ChangeInt("iMoney",-300);SharedProvisions.Add(SharedProvisions.City,10.5);VariableSingleton.ChangeInt("iTurkSpies",3);VariableSingleton.SetInt("iTurkScreeningIntercepted",1);PalaceAdministration.RecordOrder("Ordered 50 infantry","ready next week");Check(SaveGames.Checkpoint(),"administration checkpoint saved");var account=DecisionJournal.Entries.Single(e=>e.id.StartsWith("administration-"));Check(account.text.Contains("Gold: -300")&&account.text.Contains("Provisions: +10.5")&&account.text.Contains("Ordered 50 infantry"),"public deltas and order preserved");Check(!account.text.Contains("spy")&&!account.text.Contains("Spies")&&!account.text.Contains("Intercepted")&&!account.text.Contains("Turk"),"administration excludes hidden enemy intelligence");int count=DecisionJournal.Entries.Count;PalaceAdministration.Checkpoint();Check(DecisionJournal.Entries.Count==count,"unchanged checkpoint cannot duplicate accounts");Check(PalaceAdministration.Period("1 Jan 1452").Contains("1 February 1452")&&PalaceAdministration.Period("6 Apr 1453").Contains("Siege day 1"),"preparation ranges and siege days");
        Check(EventDecisionHistory.Read(new DecisionJournal.Entry{id=EventDecisionHistory.Prefix+"invalid",text="{\"format\":1,\"stages\":null}"})==null,"incomplete transcript safely rejected");
        string[] prefixes={"Expel the Turkish","Accept volunteers","Place their households","We need every man","Accept their service"};
        for(int policy=1;policy<=5;policy++){Reset();VariableSingleton.SetInt("iFocus",policy==4?1:policy==5?4:0);yield return OpenEvent("story13");FindObjectsOfType<OptionButton>().Single(o=>o.IsInteractable()&&o.Option.Line.Text.Text.StartsWith(prefixes[policy-1])).InvokeOptionSelected();yield return FinishDialogue();var entry=DecisionJournal.Entries.Single(e=>EventDecisionHistory.Read(e)?.node=="story13");var record=EventDecisionHistory.Read(entry);Check(record.stages.Count==1&&record.stages[0].choices.Count==5,"five choices recorded "+policy);Check(record.stages[0].choices.Count(c=>c.chosen)==1&&record.stages[0].choices.Single(c=>c.chosen).text.StartsWith(prefixes[policy-1]),"only actual branch marked "+policy);Check(record.stages[0].narrative.Contains("Orhan"),"full introduction retained "+policy);if(policy==3||policy==4)Check(!record.ending.Contains("Ottoman spies")&&!record.ending.Contains("iTurkSpies"),"successful infiltration hidden from history "+policy);if(policy==5)Check(record.ending.Contains("suspected Ottoman operative"),"screening interception remains public");int histories=DecisionJournal.Entries.Count(e=>EventDecisionHistory.Read(e)!=null);events.FinishEvent();Check(DecisionJournal.Entries.Count(e=>EventDecisionHistory.Read(e)!=null)==histories,"completion cannot duplicate history "+policy);Check(SaveGames.Load(VariableSingleton.SavePath,out var error),"actual outcome archive reload "+error);var restored=DecisionJournal.Entries.Single(e=>e.id==entry.id);Check(restored.text==entry.text,"full transcript survives disk load "+policy);
            events.gameObject.SetActive(false);CampaignHUD.Instance.DismissReport();string before=State();DecisionJournal.Show(DecisionJournal.Tab.Decisions);yield return null;JournalPageView.Open(restored,0,false);yield return null;Check(ReaderButton("Recorded chosen decision").interactable,"chosen option remains clickable "+policy);Check(Reader().GetComponentsInChildren<Button>().Where(b=>b.name=="Recorded unchosen decision").All(b=>!b.interactable),"all alternatives disabled "+policy);ReaderButton("Recorded chosen decision").onClick.Invoke();yield return null;Check(Reader().GetComponentsInChildren<TMP_Text>().Any(t=>t.text==record.ending),"actual outcome readable "+policy);Check(State()==before&&!runner.IsDialogueRunning,"reading outcome executes no effects or dialogue "+policy);JournalPageView.CloseReader();DecisionJournal.Close();}
        // Two-stage synthetic record exercises navigation without invoking any executable event.
        Reset();var transcript=new EventDecisionHistory.Record{node="test-chain",title="A recorded council",ending="The chosen orders were carried out."};for(int i=0;i<2;i++){var stage=new EventDecisionHistory.Stage{narrative="Recorded stage "+(i+1)};stage.choices.Add(new EventDecisionHistory.Choice{text="Chosen path "+(i+1),chosen=true});stage.choices.Add(new EventDecisionHistory.Choice{text="Road not taken "+(i+1)});transcript.stages.Add(stage);}string id=EventDecisionHistory.Prefix+"synthetic";DecisionJournal.Record(id,transcript.title,JsonUtility.ToJson(transcript),true);var synthetic=DecisionJournal.Entries.Single(e=>e.id==id);var follow=new EventDecisionHistory.Record{node="test-follow",parent=id,title="Recorded sequel",ending="The original chain ends here."};DecisionJournal.Record(EventDecisionHistory.Prefix+"follow",follow.title,JsonUtility.ToJson(follow),true);Check(SaveGames.Checkpoint()&&SaveGames.Load(VariableSingleton.SavePath,out _),"multi-stage chain saves and loads");synthetic=DecisionJournal.Entries.Single(e=>e.id==id);Check(EventDecisionHistory.Read(synthetic).stages.Count==2&&EventDecisionHistory.Followup(synthetic)!=null,"saved multi-stage/followup linkage");
        foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1600,900)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.4f);string before=State();DecisionJournal.Show(DecisionJournal.Tab.Decisions);yield return null;JournalPageView.Open(synthetic,0,false);yield return null;Check(Reader().GetComponentsInChildren<TMP_Text>().Any(t=>t.text=="Recorded stage 1"),"first stage visible "+size.x);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"reader-"+size.x+".png"));yield return new WaitForSecondsRealtime(.2f);ReaderButton("Recorded chosen decision").onClick.Invoke();yield return null;Check(Reader().GetComponentsInChildren<TMP_Text>().Any(t=>t.text=="Recorded stage 2"),"chosen path advances to actual next stage "+size.x);ReaderButton("Recorded chosen decision").onClick.Invoke();yield return null;Reader().GetComponentsInChildren<Button>().Single(b=>b.GetComponentInChildren<TMP_Text>().text=="Continue recorded decision").onClick.Invoke();yield return null;Check(Reader().GetComponentsInChildren<TMP_Text>().Any(t=>t.text==follow.ending),"only recorded sequel accessible "+size.x);Check(State()==before&&!runner.IsDialogueRunning,"entire reader is state/RNG invariant "+size.x);JournalPageView.CloseReader();DecisionJournal.Close();}
        // Actual cross-node chain remains attached after restoring its outcome checkpoint.
        Reset();yield return OpenEvent("story5");FindObjectsOfType<OptionButton>().First(o=>o.IsInteractable()).InvokeOptionSelected();yield return FinishDialogue();var parent=DecisionJournal.Entries.Single(e=>EventDecisionHistory.Read(e)?.node=="story5");events.gameObject.SetActive(false);Check(SaveGames.Load(VariableSingleton.SavePath,out var loadError),"parent outcome reloaded "+loadError);var resume=SaveGames.PendingResume;Check(resume!=null&&resume.node=="story5","resume contains completed parent node");events.ResumeCheckpoint(resume.node,resume.title,resume.report);events.ContinueToAssault();yield return new WaitForSecondsRealtime(.5f);Check(events.Node=="story4"&&runner.IsDialogueRunning,"resumed chain opens actual story4");FindObjectsOfType<OptionButton>().First(o=>o.IsInteractable()).InvokeOptionSelected();yield return FinishDialogue();var child=EventDecisionHistory.Followup(DecisionJournal.Entries.Single(e=>e.id==parent.id));Check(child!=null&&EventDecisionHistory.Read(child).node=="story4","resumed actual followup retains parent identity");
    }
}
#endif
